function L({registerIndicator:d,sourceValues:y,nulls:b}){d({id:"oa-quantile",name:"Quantile (QUANTILE)",category:"Statistics",placement:"onchart",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"length",type:"number",label:"Period",default:14,min:1,max:1e3,step:1},{key:"quantileLevel",type:"number",label:"Quantile Level (0.0-1.0)",default:.25,min:0,max:1,step:.01,tooltip:"Rank within the sorted window: 0 is the lowest value, 0.5 the median, 1 the highest."}],plots:[{key:"quantile",type:"line",title:"Quantile",style:{color:"#ffeb3b",lineWidth:2}}],calc(a,c){const v=Math.max(1,Math.floor(Number(c.length)||14)),u=c.quantileLevel,h=Number(u),s=u===""||u==null||!Number.isFinite(h)?.25:Math.min(1,Math.max(0,h)),f=y(a,c.source??"close"),n=new Array(a.length).fill(NaN),e=[];for(let t=0;t<a.length;t++){e.length=0;const k=Math.max(0,t-v+1);for(let l=k;l<=t;l++)Number.isFinite(f[l])&&e.push(f[l]);const o=e.length;if(o===0)continue;if(o===1){n[t]=e[0];continue}if(e.sort((l,g)=>l-g),s===0){n[t]=e[0];continue}if(s===1){n[t]=e[o-1];continue}const r=s*(o-1),i=Math.floor(r),m=Math.ceil(r);if(i===m){n[t]=e[i];continue}const p=e[i],w=e[m];n[t]=p+(r-i)*(w-p)}return{quantile:b(n)}}})}export{L as default};
